// Untimed validation infrastructure. No performance clocks or algorithm changes.
#include "bspai/cuda_ir.hpp"
#include <cuda_runtime.h>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <string>
#ifdef _WIN32
#define NOMINMAX
#include <windows.h>
#include <psapi.h>
#endif

namespace {
std::string quote(const std::string& s){std::ostringstream o;o<<'"';for(unsigned char c:s){switch(c){case '"':o<<"\\\"";break;case '\\':o<<"\\\\";break;case '\n':o<<"\\n";break;case '\r':o<<"\\r";break;case '\t':o<<"\\t";break;default:if(c<32)o<<"\\u00"<<std::hex<<std::setw(2)<<std::setfill('0')<<static_cast<unsigned>(c)<<std::dec;else o<<c;}}o<<'"';return o.str();}
const char* reason(double v){return std::isnan(v)?"nan":(v<0?"negative_infinity":"positive_infinity");}
void field(std::ostream& o,const char* key,double v){o<<quote(key)<<':';if(std::isfinite(v))o<<v;else o<<"null,"<<quote(std::string(key)+"_reason")<<':'<<quote(reason(v));}
template<class T>void integers(std::ostream& o,const std::vector<T>& v){o<<'[';for(std::size_t i=0;i<v.size();++i){if(i)o<<',';o<<v[i];}o<<']';}
void numbers(std::ostream& o,const std::vector<double>& v){o<<'[';for(std::size_t i=0;i<v.size();++i){if(i)o<<',';if(std::isfinite(v[i]))o<<v[i];else o<<"{\"value\":null,\"reason\":"<<quote(reason(v[i]))<<'}';}o<<']';}
void matrix(std::ostream& o,const bspai::CsrMatrix& a){o<<"{\"rows\":"<<a.rows()<<",\"cols\":"<<a.cols()<<",\"nnz\":"<<a.values().size()<<",\"offsets\":";integers(o,a.row_offsets());o<<",\"indices\":";integers(o,a.column_indices());o<<",\"values\":";numbers(o,a.values());o<<'}';}
void gmres(std::ostream& o,const bspai::GmresResult& r){o<<"{\"status\":"<<quote(bspai::gmres_status_name(r.status))<<",\"message\":"<<quote(r.message)<<",\"converged\":"<<r.converged<<",\"iterations\":"<<r.iterations<<",\"x\":";numbers(o,r.solution);o<<',';field(o,"initial_original_residual",r.initial_original_residual);o<<',';field(o,"initial_preconditioned_relative",r.initial_preconditioned_relative);o<<',';field(o,"final_original_residual",r.final_original_residual);o<<',';field(o,"final_preconditioned_relative",r.final_preconditioned_relative);o<<",\"history\":[";for(std::size_t j=0;j<r.history.size();++j){if(j)o<<',';const auto& h=r.history[j];o<<"{\"iteration\":"<<h.iteration<<",\"x\":";numbers(o,h.solution);o<<',';field(o,"estimate",h.estimated_relative);o<<',';field(o,"recomputed",h.recomputed_relative);o<<',';field(o,"original_residual",h.original_residual);o<<',';field(o,"arnoldi_subdiagonal",h.arnoldi_subdiagonal);o<<",\"accepted\":"<<h.accepted<<",\"breakdown\":"<<h.breakdown<<",\"verification_triggered\":"<<h.verification_triggered<<'}';}o<<"]}";}
void construction(std::ostream& o,const bspai::SpaiResult& r){o<<"{\"status\":"<<quote(bspai::spai_status_name(r.status))<<",\"message\":"<<quote(r.message)<<",\"scaling\":";numbers(o,r.scaling);o<<",\"B\":";matrix(o,r.scaled_transpose);o<<",\"N\":";matrix(o,r.inverse);o<<",\"P\":";matrix(o,r.preconditioner);o<<",\"columns\":[";for(std::size_t k=0;k<r.columns.size();++k){if(k)o<<',';const auto& c=r.columns[k];o<<"{\"column\":"<<k<<",\"status\":"<<quote(bspai::spai_status_name(c.status))<<",\"message\":"<<quote(c.message)<<",\"pattern\":";integers(o,c.pattern);o<<",\"attempted_pattern\":";integers(o,c.attempted_pattern);o<<",\"coefficients\":";numbers(o,c.coefficients);o<<",\"fits\":"<<c.fits<<",\"growths\":"<<c.growths<<",\"fit_attempts\":"<<c.fit_attempts<<",\"growth_attempts\":"<<c.growth_attempts<<",\"score_clamps\":"<<c.score_clamps<<',';field(o,"residual",c.reduced_residual);o<<',';field(o,"full_residual",c.full_residual);o<<',';field(o,"pivot_ratio",c.qr_pivot_ratio);o<<",\"history\":[";for(std::size_t j=0;j<c.history.size();++j){if(j)o<<',';const auto& f=c.history[j];o<<"{\"J\":";integers(o,f.pattern);o<<",\"I\":";integers(o,f.shadow);o<<",\"coefficients\":";numbers(o,f.coefficients);o<<",\"candidates\":";integers(o,f.candidates);o<<",\"scores\":";numbers(o,f.scores);o<<",\"selected\":";integers(o,f.selected);o<<',';field(o,"residual",f.residual);o<<',';field(o,"full_residual",f.full_residual);o<<',';field(o,"mean_score",f.mean_score);o<<',';field(o,"pivot_ratio",f.qr_pivot_ratio);o<<'}';}o<<"]}";}o<<"]}";}
void diagnostic(std::ostream& o,const bspai::IrDiagnostics& d){o<<"{\"r\":";numbers(o,d.residual);o<<',';field(o,"residual_inf",d.residual_inf);o<<',';field(o,"residual_2",d.residual_2);o<<',';field(o,"normwise_backward_error",d.normwise_backward_error);o<<',';field(o,"componentwise_backward_error",d.componentwise_backward_error);o<<',';field(o,"forward_error",d.forward_error);o<<",\"has_reference\":"<<d.has_reference<<",\"forward_diagnostic_overflow\":"<<d.forward_diagnostic_overflow<<",\"forward_diagnostic_message\":"<<quote(d.forward_diagnostic_message)<<'}';}
void solver(std::ostream& o,const bspai::IrResult& r){o<<"{\"status\":"<<quote(bspai::ir_status_name(r.status))<<",\"message\":"<<quote(r.message)<<",\"converged\":"<<r.converged<<",\"outer_steps\":"<<r.outer_steps<<",\"inner_attempts\":"<<r.inner_attempts<<",\"x\":";numbers(o,r.solution);o<<",\"outer_history\":[";for(std::size_t j=0;j<r.history.size();++j){if(j)o<<',';const auto& h=r.history[j];o<<"{\"step\":"<<h.step<<",\"x\":";numbers(o,h.x);o<<",\"diagnostics\":";diagnostic(o,h.diagnostics);o<<'}';}o<<"],\"inner_history\":[";for(std::size_t j=0;j<r.inner_history.size();++j){if(j)o<<',';o<<"{\"rhs\":";numbers(o,r.correction_rhs[j]);o<<",\"update_applied\":"<<r.update_applied[j]<<",\"gmres\":";gmres(o,r.inner_history[j]);o<<'}';}o<<"]}";}
void transfers(std::ostream& o,const bspai::CudaGmresTransfers& t){o<<"{\"vector_uploads\":"<<t.vector_uploads<<",\"vector_downloads\":"<<t.vector_downloads<<",\"arnoldi_vector_uploads\":"<<t.arnoldi_vector_uploads<<",\"arnoldi_vector_downloads\":"<<t.arnoldi_vector_downloads<<",\"scalar_observations\":"<<t.scalar_observations<<",\"dot_observations\":"<<t.dot_observations<<",\"norm_observations\":"<<t.norm_observations<<",\"finite_flag_observations\":"<<t.finite_flag_observations<<",\"host_scalar_inputs\":"<<t.host_scalar_inputs<<'}';}
void telemetry(std::ostream& o,const bspai::CudaSpaiTelemetry& t){o<<"{\"vendor_internal_excluded\":true,\"allocation_calls\":"<<t.device_allocation_calls<<",\"allocated_bytes\":"<<t.device_allocated_bytes<<",\"current_bytes\":"<<t.current_device_bytes<<",\"peak_bytes\":"<<t.peak_device_bytes<<",\"max_allocation_bytes\":"<<t.max_single_allocation_bytes<<",\"outstanding_allocations\":"<<t.outstanding_device_allocations<<",\"sparse_B_bytes\":"<<t.sparse_b_bytes<<",\"packed_output_bytes\":"<<t.packed_output_bytes<<",\"max_m\":"<<t.max_reduced_rows<<",\"max_q\":"<<t.max_pattern_columns<<",\"max_mq\":"<<t.max_reduced_elements<<",\"max_workspace_bytes\":"<<t.max_qr_workspace_bytes<<",\"max_slot_bytes\":"<<t.max_slot_bytes<<",\"nnz_B\":"<<t.nnz_b<<",\"nnz_N\":"<<t.nnz_n<<",\"nnz_P\":"<<t.nnz_p<<",\"uploads\":"<<t.uploads<<",\"downloads\":"<<t.downloads<<",\"upload_bytes\":"<<t.upload_bytes<<",\"download_bytes\":"<<t.download_bytes<<",\"streams\":"<<t.streams_created<<",\"max_fit_batch\":"<<t.max_fit_batch<<",\"qr_submissions\":"<<t.qr_submissions<<",\"max_qr_before_collection\":"<<t.max_qr_submissions_before_collection<<'}';}
void memory(std::ostream& o,bool gpu){o<<'{';bool comma=false;
#ifdef _WIN32
MEMORYSTATUSEX m{};m.dwLength=sizeof(m);if(GlobalMemoryStatusEx(&m)){o<<"\"host_available_physical_bytes\":"<<m.ullAvailPhys<<",\"host_total_physical_bytes\":"<<m.ullTotalPhys;comma=true;}PROCESS_MEMORY_COUNTERS p{};if(GetProcessMemoryInfo(GetCurrentProcess(),&p,sizeof(p))){if(comma)o<<',';o<<"\"process_working_set_bytes\":"<<p.WorkingSetSize<<",\"process_peak_working_set_bytes\":"<<p.PeakWorkingSetSize;comma=true;}
#endif
if(gpu){std::size_t free=0,total=0;const auto status=cudaMemGetInfo(&free,&total);if(comma)o<<',';if(status==cudaSuccess)o<<"\"gpu_free_bytes\":"<<free<<",\"gpu_total_bytes\":"<<total;else o<<"\"gpu_memory_snapshot_error\":"<<quote(cudaGetErrorString(status));}o<<'}';}
std::size_t count(const char* p){std::string s(p);if(s.empty()||s.find_first_not_of("0123456789")!=std::string::npos)throw std::invalid_argument("Invalid unsigned count");std::size_t used=0;const auto n=std::stoull(s,&used);if(used!=s.size()||n>std::numeric_limits<std::size_t>::max())throw std::invalid_argument("Invalid count range");return static_cast<std::size_t>(n);}
bspai::CsrMatrix load(const std::string& path){std::ifstream f(path);if(!f)throw std::invalid_argument("Cannot open input: "+path);return bspai::read_matrix_market(f);}
std::vector<double> vector_file(const std::string& path,std::size_t n){auto v=load(path);if(v.rows()!=n||v.cols()!=1)throw std::invalid_argument("Vector file must be n by 1 Matrix Market");return v.multiply({1});}
bool oom(const std::string& m){return m.find("out of memory")!=std::string::npos||m.find("memory allocation")!=std::string::npos||m.find("bad allocation")!=std::string::npos||m.find("bad_alloc")!=std::string::npos;}
}

int main(int argc,char** argv){std::cout<<std::setprecision(17)<<std::boolalpha;std::ostringstream out;out<<std::setprecision(17)<<std::boolalpha;
std::string classification="unsupported_input",substatus="invalid_input",message,phase=argc>2?argv[2]:"",backend=argc>3?argv[3]:"";const bool gpu=backend=="gpu_native"||backend=="gpu_fixed_p";out<<"{\"schema_version\":1,\"untimed\":true,\"validation_outcome\":\"unvalidated\",\"phase\":"<<quote(phase)<<",\"backend\":"<<quote(backend)<<",\"memory_before\":";memory(out,gpu);
try{
    if(argc!=12)throw std::invalid_argument("Usage: untimed_screen matrix.mtx phase[metadata|construct|solve] backend[cpu_native|gpu_native|cpu_fixed_p|gpu_fixed_p] rhs[equal_unit2|periodic7|zero|file:path] epsilon alpha beta innercap outercap P.mtx-or-- reference.mtx-or--");
    if(phase!="metadata"&&phase!="construct"&&phase!="solve")throw std::invalid_argument("Invalid phase");if(backend!="cpu_native"&&backend!="gpu_native"&&backend!="cpu_fixed_p"&&backend!="gpu_fixed_p")throw std::invalid_argument("Invalid backend");
    const auto a=load(argv[1]);out<<",\"A\":";matrix(out,a);if(!a.rows()||a.rows()!=a.cols())throw std::invalid_argument("Require nonempty square matrix");
    bspai::IrOptions options;std::size_t used=0;const std::string eps(argv[5]);options.spai.epsilon=std::stod(eps,&used);if(used!=eps.size()||!std::isfinite(options.spai.epsilon)||options.spai.epsilon<=0)throw std::invalid_argument("Invalid epsilon");options.spai.alpha=count(argv[6]);options.spai.beta=count(argv[7]);options.gmres.max_iterations=count(argv[8]);options.max_outer_steps=count(argv[9]);if(options.gmres.max_iterations>a.rows()||options.max_outer_steps>20)throw std::invalid_argument("Invalid frozen caps");
    std::vector<double> b(a.rows()),reference;const std::string rhs(argv[4]);if(rhs=="equal_unit2")b.assign(a.rows(),1/std::sqrt(static_cast<double>(a.rows())));else if(rhs=="zero"){}else if(rhs=="periodic7"){reference.resize(a.rows());for(std::size_t i=0;i<a.rows();++i)reference[i]=static_cast<double>(static_cast<int>(i%7)-3)/4;b=a.multiply(reference);}else if(rhs.compare(0,5,"file:")==0)b=vector_file(rhs.substr(5),a.rows());else throw std::invalid_argument("Invalid RHS method");if(std::string(argv[11])!="-")reference=vector_file(argv[11],a.rows());
    out<<",\"rhs_method\":"<<quote(rhs)<<",\"b\":";numbers(out,b);out<<",\"reference\":";numbers(out,reference);out<<",\"options\":{\"epsilon\":"<<options.spai.epsilon<<",\"alpha\":"<<options.spai.alpha<<",\"beta\":"<<options.spai.beta<<",\"tau\":"<<options.gmres.tolerance<<",\"innercap\":"<<options.gmres.max_iterations<<",\"outercap\":"<<options.max_outer_steps<<",\"backward_tolerance\":"<<bspai::ir_backward_tolerance()<<"}";
    if(phase=="metadata"){classification="not_run";substatus="not_run";message="Metadata only: solver not run";}
    else if(phase=="construct"){bspai::SpaiResult c(a.rows());bspai::CudaSpaiTelemetry t;if(gpu){auto r=bspai::cuda_construct_spai(a,options.spai);c=std::move(r.construction);t=r.telemetry;}else c=bspai::construct_spai(a,options.spai);classification=c.status==bspai::SpaiStatus::success?"construction_success":(c.status==bspai::SpaiStatus::invalid_input?"unsupported_input":"construction_failure");substatus=bspai::spai_status_name(c.status);message=c.message;out<<",\"construction\":";construction(out,c);if(gpu){out<<",\"gpu_spai_telemetry\":";telemetry(out,t);}}
    else{const bool fixed=backend=="cpu_fixed_p"||backend=="gpu_fixed_p";bspai::IrResult r(a.rows());bspai::CudaIrResult g(a.rows());if(fixed){const auto p=load(argv[10]);out<<",\"supplied_P\":";matrix(out,p);if(gpu)g=bspai::cuda_refine_with_preconditioner(a,p,b,options,reference);else r=bspai::refine_with_preconditioner(a,p,b,options,reference);}else if(gpu)g=bspai::cuda_gpu_spai_gmres_ir(a,b,options,reference);else r=bspai::spai_gmres_ir(a,b,options,reference);if(gpu)r=std::move(g.solver);classification=r.converged?"solver_success":(r.status==bspai::IrStatus::construction_failure?"construction_failure":(r.status==bspai::IrStatus::invalid_input?"unsupported_input":"solver_nonconvergence"));substatus=bspai::ir_status_name(r.status);message=r.message;out<<",\"construction_performed\":"<<r.construction_performed;if(r.construction_performed){out<<",\"construction\":";construction(out,r.construction);}out<<",\"solver\":";solver(out,r);if(gpu){out<<",\"context_constructions\":"<<g.context_constructions<<",\"matrix_uploads\":"<<g.matrix_uploads<<",\"gpu_spai_telemetry\":";telemetry(out,g.gpu_spai_telemetry);out<<",\"construction_transfers\":";transfers(out,g.construction_transfers);out<<",\"total_transfers\":";transfers(out,g.total_transfers);out<<",\"inner_transfers\":[";for(std::size_t j=0;j<g.inner_transfers.size();++j){if(j)out<<',';transfers(out,g.inner_transfers[j]);}out<<']';}}
}catch(const std::bad_alloc& e){classification="resource_abort";substatus="allocation_failure";message=e.what();}
catch(const std::invalid_argument& e){classification="unsupported_input";substatus="invalid_input";message=e.what();}
catch(const std::out_of_range& e){classification="unsupported_input";substatus="invalid_input";message=e.what();}
catch(const std::exception& e){message=e.what();classification=oom(message)?"resource_abort":(phase=="construct"?"construction_failure":"solver_nonconvergence");substatus=oom(message)?"allocation_failure":"runtime_error";}
out<<",\"classification\":"<<quote(classification)<<",\"substatus\":"<<quote(substatus)<<",\"message\":"<<quote(message)<<",\"memory_after\":";memory(out,gpu);out<<",\"precision\":\"binary64\",\"double_digits\":"<<std::numeric_limits<double>::digits<<",\"long_double_digits\":"<<std::numeric_limits<long double>::digits;
#ifdef _MSC_VER
out<<",\"compiler\":\"MSVC\",\"compiler_version\":"<<_MSC_VER;
#else
out<<",\"compiler\":"<<quote(__VERSION__);
#endif
out<<'}';std::cout<<out.str()<<'\n';return 0;}
